def svg(nome, estilo="linha", classe="ic"):
    """O ícone pronto para pôr no HTML (sem texto: quem usa põe o rótulo ou aria-label). Nome desconhecido = vazio."""
    if nome not in ICONES:
        return ""
    if estilo == "emoji":
        return f'<span class="{classe} ic-emoji" aria-hidden="true">{EMOJI[nome]}</span>'
    desenho = ICONES[nome][2 if estilo == "preenchido" else 1]
    return f'<svg class="{classe}" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true">{desenho}</svg>'


def sprite(nomes=None, estilo="linha", prefixo="i-"):
    """Os ícones como <symbol> num <svg> escondido, para telas que desenham no navegador:
    <svg class="ic"><use href="#i-NOME"/></svg>. Sem `nomes` = a galeria inteira."""
    escolhidos = [n for n in (nomes or ICONES) if n in ICONES]
    lado = 2 if estilo == "preenchido" else 1
    simbolos = "".join(f'<symbol id="{prefixo}{n}" viewBox="0 0 256 256">{ICONES[n][lado]}</symbol>' for n in escolhidos)
    return f'<svg width="0" height="0" style="position:absolute" aria-hidden="true">{simbolos}</svg>'


def para_o_painel():
    """A lista para o seletor de ícones: [{nome, rotulo, linha, preenchido, emoji}]."""
    return [{"nome": n, "rotulo": r, "linha": li, "preenchido": pr, "emoji": EMOJI[n]} for n, (r, li, pr) in ICONES.items()]
